import{_ as r}from"./chunks/2.CplItiQF.js";import{_ as n}from"./chunks/image1.YJCAcCic.js";import{_ as s}from"./chunks/image1.CDwWxNA4.js";import{_ as l,a as t}from"./chunks/image.DXQ6aG5l.js";import{_ as c}from"./chunks/image4.CE4zF3Ef.js";import{_ as d}from"./chunks/image6.BT6bI8ah.js";import{_ as h,a as o,b as g,c as m}from"./chunks/community.D8XXOc5B.js";import{_ as p}from"./chunks/image6.Cdq5CsCC.js";import{_ as u,C as _,o as y,c as f,ak as i,E as b}from"./chunks/framework.Db7dlGMu.js";const x="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image1.qXF34b0D.png",w="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image2.5foebaWf.png",v="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image1.DKnqGZVY.png",k="/projects/DaDablock-AI-Vision-Kit/en/advanced-kit/assets/image3.C5jrBseL.png",G=JSON.parse('{"title":"3.2 Color Scanner","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Creative Building & Styling/3.2 Color Scanner.md","filePath":"docs/3. Creative Building & Styling/3.2 Color Scanner.md"}'),z={name:"docs/3. Creative Building & Styling/3.2 Color Scanner.md"};function q(C,e,P,S,T,A){const a=_("pdf");return y(),f("div",null,[e[0]||(e[0]=i('<h1 id="_3-2-color-scanner" tabindex="-1">3.2 Color Scanner <a class="header-anchor" href="#_3-2-color-scanner" aria-label="Permalink to &quot;3.2 Color Scanner&quot;">​</a></h1><h2 id="_3-2-1-lesson-introduction" tabindex="-1">3.2.1 Lesson Introduction <a class="header-anchor" href="#_3-2-1-lesson-introduction" aria-label="Permalink to &quot;3.2.1 Lesson Introduction&quot;">​</a></h2><p>The Color Scanner is a practical robotic vision inspection model. The front of the model is equipped with the WonderLens vision module as its visual sensor, while the body incorporates a dot matrix display to output recognized color text. The modular mechanical structure ensures straightforward assembly and accessible wiring. When the camera captures a color swatch and completes color matching, the display outputs the corresponding color name. This project provides hands-on experience with AI color recognition and synchronized hardware interactions.</p><img loading="lazy" height="1080" width="1080" src="'+r+'" class="common_img" style="width:300px;aspect-ratio:1080 / 1080;"><h2 id="_3-2-2-learning-objectives" tabindex="-1">3.2.2 Learning Objectives <a class="header-anchor" href="#_3-2-2-learning-objectives" aria-label="Permalink to &quot;3.2.2 Learning Objectives&quot;">​</a></h2><ol><li>Master color recognition using the WonderLens vision module. Learn methods for reading color recognition data and calibrating tolerance parameters.</li><li>Program character display sequences on the dot matrix module. Master programming logic involving variable counting and multi-branch conditional statements.</li><li>Establish coordinated programming between the vision module and the dot matrix display. Synchronize color recognition outputs with on-screen text feedback.</li><li>Assemble the robotic model and debug the program. Develop foundational skills in building and customizing AI visual inspection projects.</li></ol><h2 id="_3-2-3-assembly-guide" tabindex="-1">3.2.3 Assembly Guide <a class="header-anchor" href="#_3-2-3-assembly-guide" aria-label="Permalink to &quot;3.2.3 Assembly Guide&quot;">​</a></h2>',7)),b(a,{src:"../../_static/shared/pdf/chapter_3/2.pdf"}),e[1]||(e[1]=i('<h2 id="_3-2-4-hardware-wiring" tabindex="-1">3.2.4 Hardware Wiring <a class="header-anchor" href="#_3-2-4-hardware-wiring" aria-label="Permalink to &quot;3.2.4 Hardware Wiring&quot;">​</a></h2><p>Connect the WonderLens vision module cable to the <strong>P1</strong> port of the ESP32 controller.</p><p>Connect the dot matrix module cable to the <strong>P5</strong> port of the ESP32 controller.</p><p>Wiring diagram:</p><img loading="lazy" height="851" width="1490" src="'+x+'" class="common_img" style="width:500px;aspect-ratio:1490 / 851;"><h2 id="_3-2-5-programming" tabindex="-1">3.2.5 Programming <a class="header-anchor" href="#_3-2-5-programming" aria-label="Permalink to &quot;3.2.5 Programming&quot;">​</a></h2><h3 id="_1-program-schematic" tabindex="-1">(1) Program Schematic <a class="header-anchor" href="#_1-program-schematic" aria-label="Permalink to &quot;(1) Program Schematic&quot;">​</a></h3><img loading="lazy" height="450" width="370" src="'+w+'" class="common_img" style="width:350px;aspect-ratio:370 / 450;"><h3 id="_2-adding-extensions" tabindex="-1">(2) Adding Extensions <a class="header-anchor" href="#_2-adding-extensions" aria-label="Permalink to &quot;(2)  Adding Extensions&quot;">​</a></h3><ul><li>Click the <strong>Extensions</strong> button and select the <strong>WonderLens</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+n+'" class="common_img" style="width:800px;aspect-ratio:1920 / 1040;"><ul><li>Click the <strong>Extensions</strong> button and select <strong>Dot matrix module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+s+'" class="common_img" style="width:800px;aspect-ratio:1920 / 1040;"><h3 id="_3-core-blocks" tabindex="-1">(3) Core Blocks <a class="header-anchor" href="#_3-core-blocks" aria-label="Permalink to &quot;(3) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Function Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:251 / 114;" height="114" width="251" src="'+l+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:75 / 67;" height="67" width="75" src="'+t+'" class="common_img"></td><td style="text-align:left;">Adjusts the brightness of the dot matrix display to a specified level from 1 to 8.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:528 / 107;" height="107" width="528" src="'+c+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:75 / 67;" height="67" width="75" src="'+t+'" class="common_img"></td><td style="text-align:left;">Displays custom text at the specified coordinates on the dot matrix display.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:255 / 101;" height="101" width="255" src="'+d+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:75 / 67;" height="67" width="75" src="'+t+'" class="common_img"></td><td style="text-align:left;">Draws the selected pattern on the dot matrix display.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:760 / 412;" height="412" width="760" src="'+h+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:91 / 55;" height="55" width="91" src="'+o+'" class="common_img"></td><td style="text-align:left;">Switches the AI vision operating mode of the vision module.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:432 / 117;" height="117" width="432" src="'+g+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:91 / 55;" height="55" width="91" src="'+o+'" class="common_img"></td><td style="text-align:left;">Refreshes the camera feed and reads recognition data for the current vision mode.</td></tr><tr><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:475 / 90;" height="90" width="475" src="'+v+'" class="common_img"></td><td style="text-align:center;"><img loading="lazy" style="aspect-ratio:91 / 55;" height="55" width="91" src="'+o+'" class="common_img"></td><td style="text-align:left;">Detects whether the target color appears in the camera frame and returns a boolean result.</td></tr></tbody></table><h3 id="_4-complete-program" tabindex="-1">(4) Complete Program <a class="header-anchor" href="#_4-complete-program" aria-label="Permalink to &quot;(4) Complete Program&quot;">​</a></h3><ol><li><p>Initialization: At startup, initialize the WonderLens vision module at port <strong>P1</strong> and switch the operating mode to color recognition. Initialize the dot matrix module at port <strong>P5</strong> and set its display brightness.</p></li><li><p>Main Loop: The program continuously updates and retrieves recognition data from the WonderLens vision module, then sequentially evaluates the detected color ID. When ID 1 is recognized, the dot matrix module displays the character &quot;R&quot; at coordinates (0, 6). When ID 2 is recognized, it displays &quot;G&quot;. When ID 3 is recognized, it displays &quot;B&quot;. If none of the three colors are detected, the dot matrix module displays a default icon. Each loop iteration pauses for 0.01 s.</p></li></ol><img loading="lazy" height="808" width="500" src="'+k+'" class="common_img" style="width:500px;aspect-ratio:500 / 808;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1gpd83ho-Cf-T1LV6VETKvwf1mI7A8Bfg?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-2-6-program-upload" tabindex="-1">3.2.6 Program Upload <a class="header-anchor" href="#_3-2-6-program-upload" aria-label="Permalink to &quot;3.2.6 Program Upload&quot;">​</a></h2><img loading="lazy" height="360" width="640" src="'+p+'" class="common_img" style="width:800px;aspect-ratio:640 / 360;"><h2 id="_3-2-7-expansion-and-challenge" tabindex="-1">3.2.7 Expansion and Challenge <a class="header-anchor" href="#_3-2-7-expansion-and-challenge" aria-label="Permalink to &quot;3.2.7 Expansion and Challenge&quot;">​</a></h2><p><strong>Challenge Task 1: Tiered Subtitle Interactive Color Scanner</strong></p><ol><li><p>Project Goal: Differentiate between single color recognition and cumulative recognition scenarios to create tiered subtitle transitions. When recognizing a single color, the display outputs the corresponding color name. Upon consecutively recognizing more than three distinct colors, the display switches to show the cumulative total of recognized colors rather than individual names.</p></li><li><p>Implementation Strategy: Call the block that reads the recognized color, introduce a numerical variable to count distinct colors, and nest multiple conditional statements. Write two separate display routines for the dot matrix module, switching the displayed content based on the variable value.</p></li><li><p>Key Challenges: Accurately filtering duplicate color detections to prevent repetitive counting, avoiding logical conflicts across nested conditions, and eliminating screen flickering during text transitions.</p></li></ol><p><strong>Challenge Task 2: Sound and Light Synchronized Color Recognition Device</strong></p><ol><li><p>Project Goal: Trigger multi-peripheral synchronized responses upon detecting color blocks. When different colors are detected, the dot matrix module displays corresponding subtitles, the onboard RGB lights illuminate in matching colors, and the buzzer plays distinct audio tones, simulating industrial material sorting alerts.</p></li><li><p>Implementation Strategy: Retain the existing color detection logic, adding blocks inside each color branch to adjust RGB colors and play buzzer tones. Assign unique light parameters and audio feedback to each color, achieving synchronized multi-device responses.</p></li><li><p>Key Challenges: Ensuring fluid camera recognition without frame drops, synchronizing light, audio, and screen output, and keeping acoustic and visual feedback distinct across colors.</p></li></ol><p><strong>Challenge Task 3: Creative Applications of Color Recognition</strong></p><ol><li><p>Smart Sorting Rover: Retain the core color recognition code and install a servo-driven paddle mechanism. When detecting different colored materials, the servo shifts items into corresponding sorting channels.</p></li><li><p>Intelligent Color Swatch Tester: Mount the sensor on a motorized linear slide to scan multiple color swatches in sequence, automatically tallying and displaying all detected colors on the dot matrix module.</p></li><li><p>Universal Adaptation Strategy: Keep the core color recognition algorithm unchanged and swap out or add output hardware. By implementing new peripheral control blocks under the logic of triggering actions upon detecting specified colors, diverse smart vision applications can be created.</p></li></ol><h2 id="_3-2-8-q-a" tabindex="-1">3.2.8 Q&amp;A <a class="header-anchor" href="#_3-2-8-q-a" aria-label="Permalink to &quot;3.2.8 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: Which module is responsible for detecting object colors, and how does it work?</strong></p><p><strong>Answer</strong>: The WonderLens vision module is responsible for detecting object colors. The onboard camera captures images of the scene, extracts RGB color data from detected color swatches, and matches these values against pre-calibrated reference templates. Once the corresponding color is determined, the module transmits the recognition data to the ESP32 controller. The controller reads this data and drives the dot matrix module to display the appropriate subtitle, completing the recognition and feedback loop.</p><p><strong>Question 2: What is the color recognition tolerance parameter, and why does tolerance affect recognition accuracy?</strong></p><p><strong>Answer</strong>: Tolerance defines the allowable color error range during matching. A smaller tolerance value enforces stricter matching criteria, meaning only color swatches highly similar to the reference template are recognized. A larger tolerance value broadens the matching range, allowing colors with slight variations to be classified as the same color. Setting tolerance too low risks failing to detect target colors, while setting it too high causes false positives from ambient lighting or background interference. During practical operation, calibrate the tolerance according to ambient lighting and background conditions to ensure reliable detection.</p><h2 id="_3-2-9-technical-support-and-product-discussion" tabindex="-1">3.2.9 Technical Support and Product Discussion <a class="header-anchor" href="#_3-2-9-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.2.9 Technical Support and Product Discussion&quot;">​</a></h2><p>Share project ideas and connect with other makers on the <a href="https://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder community</a>:</p><a href="https://forum.hiwonder.com.cn/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+m+'" class="common_img" style="width:800px;aspect-ratio:1136 / 640;"></a>',36))])}const K=u(z,[["render",q]]);export{G as __pageData,K as default};
